		fmt.Fprintf(tw, "%s\t%.2f GB\t%.1f\t%.1f\t%.0f%%\t%d\n",
			k, a.q4Bytes/1e9, a.flops/1e9, a.flops/a.q4Bytes, 100*a.memBytes/a.q4Bytes, a.dispatches)
	}
