		if math.Signbit(float64(got)) != math.Signbit(float64(c.want)) {
			t.Errorf("f16ToF32(%04x) sign mismatch: %v vs %v", c.h, got, c.want)
		}
	}
}

// TestOpenRoundTrip writes a small checkpoint by hand and reads it back,
