// Shared binding and push-constant layout for the VAE decoder shaders.
//
// Every decoder pipeline declares the *same* two buffers and the *same*
// push-constant size, because vk.DispatchMultiTimed records a whole graph
// into one command buffer and requires that. It is also the right shape for
// an engine: weights are one arena written once, activations are one arena
// the graph ping-pongs inside, and "which tensor" is an offset rather than a
// descriptor rebind.
//
// All arithmetic is fp32 here. Stage 2b is a correctness port with the CPU
// implementation in zimage/vae as its oracle; moving the weights to fp16 and
// the matmuls onto the WMMA path is a separate change with its own
// measurement, and doing both at once would leave a numerical discrepancy
// with two possible causes.

layout(binding = 0) readonly buffer Weights { float wbuf[]; };
layout(binding = 1) buffer Act { float act[]; };

layout(push_constant) uniform PC {
    uint inOff;    // element offset of the input tensor in act
    uint outOff;   // element offset of the output tensor in act
    uint C;        // input channels
    uint H;        // input height
    uint W;        // input width
    uint OC;       // output channels
    uint KH;       // kernel height
    uint KW;       // kernel width
    uint pad;      // symmetric zero padding
    uint wOff;     // element offset of the weight tensor in wbuf
    uint bOff;     // element offset of the bias tensor in wbuf, or NO_BIAS
    uint groups;   // group count for group norm
    uint resOff;   // element offset of the residual/second operand in act
    uint aux0;
    uint aux1;
    uint aux2;
} pc;

const uint NO_BIAS = 0xffffffffu;
EOF

cat > vae_conv2d.comp <<'EOF'
#version 450
// Direct 2-D convolution, stride 1, symmetric zero padding, weights in
// PyTorch's [OC, IC, KH, KW] order. Covers both shapes the decoder uses:
// 3x3 pad 1 and the 1x1 pad 0 residual shortcuts.
//
// One invocation per output element. The reduction is over IC*KH*KW, which
// is 4608 for the 512->512 3x3 convolutions that dominate this graph.

#include "vae_common.glsl"

layout(local_size_x = 64) in;

void main() {
    uint idx = gl_GlobalInvocationID.x;
    uint outHW = pc.H * pc.W;               // stride 1 with pad preserves H,W
    uint total = pc.OC * outHW;
    if (idx >= total) {
        return;
    }

    uint ow = idx % pc.W;
    uint oh = (idx / pc.W) % pc.H;
    uint oc = idx / outHW;

    float sum = (pc.bOff == NO_BIAS) ? 0.0 : wbuf[pc.bOff + oc];

    uint tapsPerIC = pc.KH * pc.KW;
    uint wBase = pc.wOff + oc * pc.C * tapsPerIC;

    for (uint ic = 0u; ic < pc.C; ++ic) {
        uint srcBase = pc.inOff + ic * outHW;
        uint wIC = wBase + ic * tapsPerIC;
        for (uint kh = 0u; kh < pc.KH; ++kh) {
            // ih and iw are signed comparisons against the padded border;
            // doing them in int avoids the wraparound a uint subtraction
            // would hide.
            int ih = int(oh) + int(kh) - int(pc.pad);
            if (ih < 0 || ih >= int(pc.H)) {
                continue;
            }
            uint rowBase = srcBase + uint(ih) * pc.W;
            uint wRow = wIC + kh * pc.KW;
            for (uint kw = 0u; kw < pc.KW; ++kw) {
                int iw = int(ow) + int(kw) - int(pc.pad);
                if (iw < 0 || iw >= int(pc.W)) {
                    continue;
                }
                sum += wbuf[wRow + kw] * act[rowBase + uint(iw)];
            }
        }
    }
    act[pc.outOff + idx] = sum;
}
EOF

cat > vae_groupnorm.comp <<'EOF'
#version 450
// GroupNorm over (C/groups, H, W), then a per-channel scale and shift.
//
// One workgroup per group, doing the whole thing in one dispatch: reduce for
// the mean, reduce again for the variance *about that mean*, then normalise.
// Three passes over the data instead of one, and deliberately so -- the
// single-pass E[x^2]-E[x]^2 form cancels catastrophically here, where a group
// can hold 262144 values whose mean is far from zero. There is no fp64 in
// this shader, so the algorithm has to supply the conditioning instead.
//
// Each thread also accumulates its own partial before the tree reduction, so
// a group's sum is a tree over 256 partials rather than a serial chain.

#include "vae_common.glsl"

layout(local_size_x = 256) in;

shared float partial[256];

float reduceSum(float v) {
    uint t = gl_LocalInvocationID.x;
    partial[t] = v;
    barrier();
    for (uint s = 128u; s > 0u; s >>= 1) {
        if (t < s) {
            partial[t] += partial[t + s];
        }
        barrier();
    }
    float total = partial[0];
    barrier();     // keep partial[0] alive until every thread has read it
    return total;
}

void main() {
    uint g = gl_WorkGroupID.x;
    uint t = gl_LocalInvocationID.x;
    uint perGroup = pc.C / pc.groups;
    uint hw = pc.H * pc.W;
    uint count = perGroup * hw;
    uint base = pc.inOff + g * perGroup * hw;

    float s = 0.0;
    for (uint i = t; i < count; i += 256u) {
        s += act[base + i];
    }
    float mean = reduceSum(s) / float(count);

    float v = 0.0;
    for (uint i = t; i < count; i += 256u) {
        float d = act[base + i] - mean;
        v += d * d;
    }
    float variance = reduceSum(v) / float(count);
    float inv = inversesqrt(variance + uintBitsToFloat(pc.aux0));

    uint outBase = pc.outOff + g * perGroup * hw;
    for (uint i = t; i < count; i += 256u) {
        uint c = g * perGroup + i / hw;
        float scale = wbuf[pc.wOff + c] * inv;
        float shift = wbuf[pc.bOff + c] - mean * scale;
        act[outBase + i] = act[base + i] * scale + shift;
    }
}
