func splitInts(s string) []int {
	var out []int
	cur, has := 0, false
	for _, r := range s {
		if r >= '0' && r <= '9' {
			cur = cur*10 + int(r-'0')
			has = true
		} else if has {
			out = append(out, cur)
			cur, has = 0, false
		}
	}
	if has {
		out = append(out, cur)
	}
	return out
}

func must(err error) {
	if err != nil {
		log.Fatal(err)
	}
}
