#version 450
// Direct 2-D convolution, stride 1, symmetric zero padding, weights in
// PyTorch's [OC, IC, KH, KW] order. Covers both shapes the decoder uses:
// 3x3 pad 1 and the 1x1 pad 0 residual shortcuts.
//
// The grid is (spatial tiles, output channels): one workgroup owns one
// output channel and 256 consecutive output pixels, and stages that
// channel's weights through shared memory a block of input channels at a
// time.
//
// Staging is the whole point. The first version of this shader had every
// thread re-read all IC*KH*KW weights from global memory -- 4608 of them for
// the 512->512 convolutions -- and profiling put conv3x3 at 90.3% of the
// decode at ~750 GFLOP/s, which is 3% of this part's measured 22.9 TFLOP/s
// fp32 FMA ceiling. Reading each weight once per workgroup instead of once
// per thread divides that traffic by the workgroup size.
//
// The input-channel blocking is what keeps the LDS footprint off the
// occupancy: a whole 512-channel 3x3 filter is 18 KB, which would leave one
// or two workgroups resident per CU, while a 64-channel block is 2.3 KB.

#include "vae_common.glsl"

layout(local_size_x = 256) in;

const uint IC_BLOCK = 64u;
shared float shW[IC_BLOCK * 9u];

void main() {
    uint oc = gl_WorkGroupID.y;
    uint t = gl_LocalInvocationID.x;
    uint outHW = pc.H * pc.W;                 // stride 1 with pad preserves H,W
    uint p = gl_WorkGroupID.x * 256u + t;     // this thread's output pixel

    uint ow = p % pc.W;
    uint oh = p / pc.W;
    bool active = (p < outHW) && (oc < pc.OC);

    float sum = 0.0;
    if (active && pc.bOff != NO_BIAS) {
        sum = wbuf[pc.bOff + oc];
    }

    uint tapsPerIC = pc.KH * pc.KW;
    uint wBase = pc.wOff + oc * pc.C * tapsPerIC;

    for (uint ic0 = 0u; ic0 < pc.C; ic0 += IC_BLOCK) {
        uint n = min(IC_BLOCK, pc.C - ic0);
        uint span = n * tapsPerIC;
        barrier();
        for (uint i = t; i < span; i += 256u) {
            shW[i] = wbuf[wBase + ic0 * tapsPerIC + i];
        }
        barrier();

        if (!active) {
            continue;
        }
        for (uint j = 0u; j < n; ++j) {
            uint srcBase = pc.inOff + (ic0 + j) * outHW;
            uint wIC = j * tapsPerIC;
            for (uint kh = 0u; kh < pc.KH; ++kh) {
                int ih = int(oh) + int(kh) - int(pc.pad);
                if (ih < 0 || ih >= int(pc.H)) {
                    continue;
                }
                uint rowBase = srcBase + uint(ih) * pc.W;
                uint wRow = wIC + kh * pc.KW;
                for (uint kw = 0u; kw < pc.KW; ++kw) {
                    int iw = int(ow) + int(kw) - int(pc.pad);
                    if (iw < 0 || iw >= int(pc.W)) {
                        continue;
                    }
                    sum += shW[wRow + kw] * act[rowBase + uint(iw)];
                }
            }
        }
    }

    if (active) {
        act[pc.outOff + oc * outHW + p] = sum;
    }
}
