#version 450
// Flash-attention-style multi-head attention: one workgroup handles QB query
// rows of one head, streaming the keys in tiles through shared memory with an
// online softmax.
//
// This is IDEAS §3.3, and it exists because the straightforward version is
// not close to good enough. That one gives each workgroup a single query row,
// so every one of them re-reads the whole key head -- at 4096 tokens it
// measured 836 ms and 463 GFLOP/s, 0.8% of this part's 55.5 TFLOP/s matrix
// ceiling, which over 34 blocks and 8 steps is about four minutes of
// attention per image.
//
// Two changes, both of which reduce key traffic by a constant factor:
//   - QB query rows share one staged key tile, so the keys are read once per
//     workgroup instead of once per query.
//   - The running max and denominator are carried across tiles, so the keys
//     are read once rather than twice. The exponential still only ever sees
//     (score - runningMax), which is the requirement the VAE's 1.16e7 scores
//     and this block's 5.99e5 feed-forward output impose.
//
// Keys arrive transposed (dit_transpose_k.comp) so both the tile staging and
// the score loop read consecutive tokens at consecutive addresses; §5.1b's
// coverage law is what makes that worth 20x rather than a rounding error.

#include "dit_common.glsl"

const uint QB = 8u;    // query rows per workgroup
const uint KT = 32u;   // keys per tile
const uint HD = 128u;  // head dim; Z-Image is 3840/30

layout(local_size_x = 256) in;

shared float shQ[QB * HD];
shared float shK[KT * HD];
shared float shS[QB * KT];
shared float shCtx[QB * HD];
shared float shSeg[QB * KT];
shared float shM[QB];
shared float shL[QB];
shared float shCorr[QB];

void main() {
    uint head = gl_WorkGroupID.y;
    uint q0 = gl_WorkGroupID.x * QB;
    uint t = gl_LocalInvocationID.x;
    uint n = pc.tokens;
    uint D = pc.headDim;
    float scale = uintBitsToFloat(pc.scale);
    if (q0 >= n || head >= pc.heads) {
        return;
    }

    // Stage this block's queries and zero the running state.
    for (uint i = t; i < QB * D; i += 256u) {
        uint qi = i / D, d = i % D;
        uint row = q0 + qi;
        shQ[i] = (row < n) ? act[pc.inOff + row * pc.dim + head * D + d] : 0.0;
        shCtx[i] = 0.0;
    }
    if (t < QB) {
        shM[t] = -1.0 / 0.0;
        shL[t] = 0.0;
    }
    barrier();

    uint kHead = pc.kOff + head * D * pc.kStride;

    for (uint base = 0u; base < n; base += KT) {
        uint cnt = min(KT, n - base);

        // Stage the key tile. The transposed layout puts consecutive tokens
        // at consecutive addresses, so consecutive threads coalesce.
        for (uint i = t; i < KT * D; i += 256u) {
            uint d = i / KT, kk = i % KT;
            shK[d * KT + kk] = (kk < cnt) ? act[kHead + d * pc.kStride + base + kk] : 0.0;
        }
        barrier();

        // One score per thread: QB * KT is exactly the workgroup size.
        uint qi = t / KT, kk = t % KT;
        float s = 0.0;
        for (uint d = 0u; d < D; ++d) {
            s += shQ[qi * D + d] * shK[d * KT + kk];
        }
        s = (kk < cnt && q0 + qi < n) ? s * scale : -1.0 / 0.0;
        shS[t] = s;
        shSeg[t] = s;
        barrier();

        // Segmented max over each query's KT scores.
        for (uint stride = KT >> 1; stride > 0u; stride >>= 1) {
            if (kk < stride) {
                shSeg[t] = max(shSeg[t], shSeg[t + stride]);
            }
            barrier();
        }
        float tileMax = shSeg[qi * KT];
        barrier();

        // Online update: fold the tile's max into the running one and note
        // how much the already-accumulated context must shrink.
        if (t < QB) {
            float newMax = max(shM[t], tileMax);
            shCorr[t] = (shM[t] == -1.0 / 0.0) ? 0.0 : exp(shM[t] - newMax);
            shM[t] = newMax;
        }
        barrier();

        float w = exp(shS[t] - shM[qi]);
        shS[t] = w;
        shSeg[t] = w;
        barrier();
        for (uint stride = KT >> 1; stride > 0u; stride >>= 1) {
            if (kk < stride) {
                shSeg[t] += shSeg[t + stride];
            }
            barrier();
        }
        if (t < QB) {
            shL[t] = shL[t] * shCorr[t] + shSeg[t * KT];
        }
        barrier();

        // Rescale the running context, then accumulate this tile's keys.
        // Each thread owns a disjoint set of (query, component) pairs.
        for (uint i = t; i < QB * D; i += 256u) {
            uint qq = i / D, d = i % D;
            float acc = shCtx[i] * shCorr[qq];
            for (uint j = 0u; j < cnt; ++j) {
                acc += shS[qq * KT + j] * act[pc.vOff + (base + j) * pc.dim + head * D + d];
            }
            shCtx[i] = acc;
        }
        barrier();
    }

    for (uint i = t; i < QB * D; i += 256u) {
        uint qq = i / D, d = i % D;
        uint row = q0 + qq;
        if (row < n) {
            act[pc.outOff + row * pc.dim + head * D + d] = shCtx[i] / shL[qq];
        }
    }
}
