		if err != nil {
			t.Fatal(err)
		}
		defer g.Destroy()
		g.Flash = flash
		out, err := g.Apply(q.Clone(), k.Clone(), v.Clone(), false)
		if err != nil {
			t.Fatal(err)
		}
		return out
	}
	compare(t, "flash vs simple", run(true), run(false))
}
